<script setup>import {computed} from 'vue';import {state} from '../../domain/prototypeStore.js';const done=computed(()=>state.tasks.filter(x=>x.status==='已完成').length)</script>
<template><section class="page-stack"><div class="metric-grid"><article><small>当前事件</small><strong>{{state.events.filter(x=>x.status!=='已关闭').length}}</strong><span>待核实与处置中</span></article><article><small>待办任务</small><strong>{{state.tasks.filter(x=>x.status!=='已完成').length}}</strong><span>处置任务</span></article><article><small>任务完成</small><strong>{{state.tasks.length?Math.round(done/state.tasks.length*100):0}}%</strong><span>当前处置进度</span></article><article><small>异常提醒</small><strong>{{state.attendanceAlerts.filter(x=>x.status!=='已处理').length}}</strong><span>待跟进</span></article></div><div class="panel-grid"><article class="panel"><header><div><h2>事件动态</h2><p>掌握当前事件处置进展</p></div><RouterLink to="/web/incidents">进入管理</RouterLink></header><div class="event-list"><div v-for="e in state.events.slice(0,4)" :key="e.id" class="event-row"><div><strong>{{e.title}}</strong><small>{{e.location}} · {{e.type}}</small></div><span>{{e.status}}</span></div></div></article><article class="panel"><header><div><h2>资源态势</h2><p>人员、物资和设备统一查看</p></div><RouterLink to="/web/situation">打开态势</RouterLink></header><div class="map-placeholder"><b>东区展厅</b><small>事件、人员和资源状态</small></div></article></div></section></template>
